import bisect

n = int(input())
a = []
for _ in range(n):
    op, x = map(int, input().split())
    if op == 1:
        if x not in a:
            bisect.insort(a, x)
    elif op == 2:
        if x in a:
            a.remove(x)
    elif op == 3:
        print(bisect.bisect_left(a, x) + 1)
    elif op == 4:
        print(a[x - 1])
    elif op == 5:
        print(a[bisect.bisect_left(a, x) - 1])
    else:
        print(a[bisect.bisect_right(a, x)])
